const DELTAS = [];
for (let dx = -1; dx <= 1; dx++) for (let dy = -1; dy <= 1; dy++) if (!(dx===0&&dy===0)) DELTAS.push([dx,dy]);

function nextGeneration(cells) {
  const live = new Set(cells.map(([x,y]) => `${x},${y}`));
  const neighborCount = new Map();
  for (const [x,y] of cells) {
    for (const [dx,dy] of DELTAS) {
      const key = `${x+dx},${y+dy}`;
      neighborCount.set(key, (neighborCount.get(key)||0)+1);
    }
  }
  const out = [];
  const candidates = new Set([...live, ...neighborCount.keys()]);
  for (const key of candidates) {
    const n = neighborCount.get(key)||0;
    const isAlive = live.has(key);
    if (isAlive ? (n===2||n===3) : (n===3)) {
      const [x,y] = key.split(',').map(Number);
      out.push([x,y]);
    }
  }
  return out.sort((a,b) => a[1]-b[1] || a[0]-b[0]);
}

const fmt = c => JSON.stringify(c);

const cases = [
  ["empty", [], []],
